<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('qc.view');verify_csrf();$pdo=staff_db();feature_table($pdo,'qc_inspections');$staff=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$a=fpost('action');if($a==='create'){$pdo->prepare('INSERT INTO qc_inspections(inspection_code,project_id,inspection_type,status,inspected_by,overall_notes) VALUES(?,?,?,?,?,?)')->execute([op_code('QC'),fint('project_id'),fpost('inspection_type'),'pending',$staff['id'],fpost('overall_notes')?:null]);flash('success','QC inspection opened.');}elseif($a==='status'){$pdo->prepare('UPDATE qc_inspections SET status=?,inspected_at=IF(? IN ("passed","failed","conditional_pass"),NOW(),inspected_at),signed_off_by=IF(?="passed",?,signed_off_by),signed_off_at=IF(?="passed",NOW(),signed_off_at) WHERE id=?')->execute([fpost('status'),fpost('status'),fpost('status'),$staff['id'],fpost('status'),fint('id')]);flash('success','Inspection updated.');}staff_redirect('staff/pages/quality-control.php');}
$projects=project_options($pdo);$rows=db_rows($pdo,'SELECT q.*,p.project_code,p.name project_name,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) inspector FROM qc_inspections q JOIN projects p ON p.id=q.project_id LEFT JOIN staff s ON s.id=q.inspected_by ORDER BY q.created_at DESC');$pageTitle='Quality Control';require __DIR__.'/../../includes/staff/header.php';module_head('Quality','Quality Control','Create documented checks before installation and handover.');?>
<section class="staff-panel"><form method="post" class="mini-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Project<select name="project_id"><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=h($p['project_code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Inspection<select name="inspection_type"><option>production</option><option>pre_installation</option><option>post_installation</option><option>handover</option></select></label><label>Notes<input name="overall_notes"></label><button class="btn primary">Start inspection</button></form></section><section class="staff-panel table-panel"><table><thead><tr><th>Inspection</th><th>Project</th><th>Type</th><th>Inspector</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=h($r['inspection_code'])?></b></td><td><?=h($r['project_code'].' · '.$r['project_name'])?></td><td><?=h($r['inspection_type'])?></td><td><?=h($r['inspector']?:'—')?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><form method="post" class="toolbar"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>pending</option><option>in_progress</option><option>passed</option><option>conditional_pass</option><option>failed</option></select><button class="btn">Save</button></form></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>